if ( ! defined( 'ABSPATH' ) ) { exit; } function gc_member_for_user( $user_id ) { $user = get_userdata( (int) $user_id ); if ( ! $user ) { return null; } $posts = get_posts( array( 'post_type' => 'gc_member', 'post_status' => 'publish', 'posts_per_page' => 1, 'meta_query' => array( array( 'key' => 'gc_member_email', 'value' => $user->user_email, 'compare' => '=' ), ), ) ); return ! empty( $posts ) ? $posts[0] : null; } function gc_dashboard_count( $post_type, $meta_query = array() ) { $args = array( 'post_type' => $post_type, 'post_status' => 'publish', 'posts_per_page' => 1, 'fields' => 'ids', ); if ( ! empty( $meta_query ) ) { $args['meta_query'] = $meta_query; } $q = new WP_Query( $args ); return (int) $q->found_posts; } 